      SUBROUTINE SOLVECC     DIRECTS FITTING PROCEDURE AND PRINTS OUT RESULTSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM10F.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'STEPT1.CIN'C ----------------------------------------------------------------------      LOGICAL         OK, CALT      REAL            GOLD, OUTPUT(20), PAR, R      REAL            CS(NPVAR+1)      EQUIVALENCE     (CS(1),CAOLD)C      IF (.NOT. ONLY .AND. (.NOT. LSTEP .OR. NSTEPP .EQ. 1      1     .OR. BROAD))      2     WRITE (NOUT,1000) NV3, NC 1000 FORMAT (1H0,8X,'*CORRECTIONS*',/,     1        1H ,8X,'*NUMBER OF VARIED PARAMETERS = ',I5,' *',/,     2        1H ,8X,'*NUMBER OF CONSTRAINTS       = ',I5,' *',/)CC     INITIALIZE VARIABLES AND MAKE FIRST PASSC      NSTEP = -1      NGLESS = 0      IF (NCTE .EQ. 1) GO TO 10      DOPARS = .FALSE.      NCTS = 1      NCTF = NCTE - 1      IF (LSTEPN) CALL STEPIT      CALL MARCH      IF (FLUSHL) GO TO 400      CALL RETAIN      IF (FLUSHL) GO TO 400      NMARM = 0      NSTEPM = 0   10 NSTEP = 0      OK = .FALSE.      NV2 = 0      CHSMIN = - 1.0      CALL FORM      IF (NV1 .EQ. 0 .AND. NV3 .NE. 0) WRITE (NOUT,1001) NV1 1001 FORMAT (1H0,8X,'*NUMBER OF USED VARIED PARAMETERS = ',I5,' *',/,     1        1H ,8X,'*RUN DISCONTINUED*')      IF (NV1 .EQ. 0) FLUSHL = .TRUE.      IF (FLUSHL) GO TO 400      N1P1 = NV1 + 1      NMAR = 0      PAR = 0.0      PMARQ = PAR      IF (LINEAR) GO TO 100      CRIT = AMAX0(1,NC-NV1)      CALT = .FALSE.CC     ITERATE FROM HERE IF NEW LOW CHI-SQUARED FOUNDC   20 NSTEP = NSTEP + 1      IF (NSTEP .GT. 50) GO TO 200      CAOLD = CA(1,1)      IF (CA(1,1) .LT. CRIT .AND. NMAR .EQ. 0) GO TO 100      CALL INQ      DO 40 J = 2, N1P1   40 CS(J) = CA(J,1)      EPS = 0.5**NMAR      DS = 0.0      DO 42 J = 2, N1P1   42 DS = DS + CASAV(J,1)*CS(J)      IF (NMAR .EQ. 0) GO TO 50      DSM = 0.0      DO 45 J = 2, N1P1      DMX = 0.0      DO 44 K = 2, N1P1   44 DMX = DMX + CASAV(J,K)*CS(K)   45 DSM = DSM + DMX*CS(J)      DS = 2.0*DS - DSM   50 GOLD = GNORM      CALL ALTER(CS)      CSNORM = 0.0      DO 51 J = 2, N1P1      CSNORM = CSNORM + CS(J)**2   51 CONTINUE      CSNORM = SQRT(CSNORM)      IF (FLUSHL) GO TO 400      NMARO = NMAR      CALL FORM      IF (FLUSHL) GO TO 400      IF (NACTIV .EQ. 0) GO TO 210      CRIT = AMAX0(1,NC-NV1)      IF (CA(1,1) .LT. CRIT) THEN        IF (NMAR .EQ. 0) GO TO 100        IF (CALT) THEN          IF (NSTEP .GE. NSTEPM + 10) GO TO 100          IF (NMAR .GT. NMARM) GO TO 100        ELSE          NMARM = NMAR          NSTEPM = NSTEP          CALT = .TRUE.        ENDIF      ENDIF      IF (DS .EQ. 0.0) THEN        NACTIV = 0        DO 55 N = 2, N1P1        IF (ACTIV(N)) NACTIV = NACTIV + 1   55   CONTINUE        IF (NACTIV .GE. 1) THEN          GO TO 200        ELSE          GO TO 210        ENDIF      ENDIFCC     REFERENCE ON WHEN TO CHANGE RELAXATION FACTORC     KLAUS HALBACH         PAPER AT SECOND INTERNATIONALC     CONFERENCE ON MAGNET TECHNOLOGY AT OXFORD 1967CC      R = (CAOLD - CA(1,1))/DS      DSCRIT = AMIN1(0.1*CA(1,1),CRIT)      IF (R .GT. 0.8 .AND. R .LT. 1.2     1    .AND. DS .LT. DSCRIT .AND. NMAR .EQ. 0) GO TO 100      IF (GNORM .LT. 0.1*GOLD) NGLESS = NSTEP      IF (DS .LT. CRIT .AND. (GNORM .LT. 0.1*GOLD .OR.      1    (NGLESS .GE. NSTEP - 1 .AND. NGLESS .NE. 0))) GO TO 100   60 IF (R .GT. 0.75) NMAR = MAX0(0,NMAR-1)      IF (R .GT. 0.25) GO TO 20   80 IF (NMAR .GT. 6 .AND. CSNORM .LT. 0.00001) GO TO 200      NMAR = NMAR + 1      IF (NMAR .GT. 20) GO TO 200      IF (R .GT. 0.0) GO TO 20   90 DO 95 J = 2, N1P1   95 CS(J) = - CS(J)      EPS = - 0.5**NMARO      CALL ALTER(CS)      DO 92 J = 1, N1P1      DO 92 K = 1, N1P1   92 CA(J,K) = CASAV(J,K)      CALL INQ      IF (FLUSHL) GO TO 400      DO 96 J = 2, N1P1   96 CS(J) = CA(J,1)      EPS = 0.5**NMAR   97 CALL ALTER(CS)      IF (FLUSHL) GO TO 400      NMARO = NMAR      CALL FORM      IF (FLUSHL) GO TO 400      IF (NACTIV .EQ. 0) GO TO 210      CRIT = AMAX0(1,NC-NV1)      IF (CA(1,1) .EQ. 0.0 .OR. OK) GO TO 220      IF (CA(1,1) .LT. CRIT .AND. NMAR .EQ. 0) GO TO 100      IF (CA(1,1) .LT. CAOLD) THEN        GO TO 20      ELSE        GO TO 80      ENDIFCC     FITTING PROCEDURE SATISFIES CONVERGENCE TESTC  100 OK = .TRUE.      CALL INQ      DO 140 J = 2, N1P1  140 CS(J) = CA(J,1)      EPS = 0.5**NMAR      CALL ALTER(CS)      IF (FLUSHL) GO TO 400      CALL FORM      IF (FLUSHL) GO TO 400      IF (NACTIV .EQ. 0) GO TO 210      IF (LINEAR) GO TO 220      IF (CA(1,1) .LT. CAOLD) GO TO 220      DO 145 J = 2, N1P1  145 CS(J) = - CS(J)      GO TO 97CC     FAILURE TO CONVERGE -- PRINT OUT WARNING MESSAGEC  200 WRITE (NOUT,1012) 1012 FORMAT (1H0,8X,'*FAILED*',/)      IF (NC .GT. NV1) WRITE (NOUT,1015) 1015 FORMAT (1H ,8X,'*NUMBER OF CONSTRAINTS EXCEEDS   *',/,     1        1H ,8X,'*NUMBER OF VARIED PARAMETERS     *',/,     2        1H ,8X,'*IF RESULTS ARE STILL CONSIDERED *',/,     3        1H ,8X,'*UNSATISFACTORY                  *')      WRITE (NOUT,1014) 1014 FORMAT (1H ,8X,'*PLEASE SEND OUTPUT TO           *',/,     1        1H ,8X,'*DAVE CAREY                      *',/,     2        1H ,8X,'*FERMILAB, P.O. BOX 500          *',/,     3        1H ,8X,'*BATAVIA, ILL 60510, USA         *')      GO TO 220CC     VARIED PARAMETERS ALL JAMMED UP AGAINST LIMITSC  210 WRITE (NOUT,9011) 9011 FORMAT (1H ,8X,'* VARIED PARAMETERS ALL JAMMED UP  *',/,     1        1H ,8X,'* AGAINST LIMITS                   *',/,     2        1H ,8X,'* FURTHER ITERATION IS NOT POSSIBLE*')CC     CONCLUSION OF FITTING - PRINT OUT RESULTC  220 CALL INQ      IF (LSTEP .AND. .NOT. BROAD) GO TO 350      WRITE (NOUT,1013) CA(1,1) 1013 FORMAT (1H0,8X,'*COVARIANCE  (FIT',E12.5,' )')      IF (NV1 .LT. 1 .OR. ONLY) GO TO 400      CAMIN = 0.0      DO 250 J = 2, N1P1      CA(1,J) = SQRT(AMAX1(CA(J,J),CAMIN))  250 CONTINUEC      DO 300 J = 2, N1P1      IF (J .LE. 2) THEN        WRITE (NOUT,1020) CA(1,J)      ELSE        JMIN1 = J - 1        DO 280 K = 2, JMIN1        OUTPUT(K) = CA(J,K) /(DEN(CA(1,J) * CA(1,K)))  280   CONTINUE        WRITE (NOUT,1020) (OUTPUT(K), K = 2, JMIN1), CA(1,J) 1020   FORMAT (1X,10F12.3)      ENDIF  300 CONTINUE      GO TO 400C  350 IF (NSTEPP .EQ. 1) WRITE (NOUT,1017)  1017 FORMAT (8X,'STEPPED PARAMETER VALUE',4X,'CHI-SQUARED',/)      WRITE (NOUT,1016) DATA(ISTEP), CA(1,1) 1016 FORMAT (15X,F12.5,7X,E12.5)C  400 RETURNC      END